  if (
    tick?.action !== 'launch' ||
    tick.campaign_id !== pin.campaign_id ||
    tick.day !== clock.day ||
    clock.day < pin.start_date ||
    clock.day > pin.end_date ||
    clock.hour < 6 ||
    clock.hour >= 12 ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(tick.run_id ?? '')
  )
    throw Error('M06_CAMPAIGN_LAUNCH_INVALID');
